    const reg=$('#personality-regression-graph');if(reg)reg.innerHTML=buildDeltaChart(delta);
    const detail=$('#personality-regression-detail');if(detail){const scenarioRegressions=comparisons.scenario_regressions||[],improvements=comparisons.improvements||[],persistent=comparisons.persistent_failures||[];detail.innerHTML=`<h4>Scenario changes</h4>${scenarioRegressions.length?scenarioRegressions.map(item=>`<div class="notice error-notice"><strong>${esc(item.scenario_id)} · ${esc(item.dimension)}</strong> ${esc(item.previous_score)} → ${esc(item.current_score)} (${esc(item.delta)}) · ${esc(item.status.replaceAll('_',' '))}</div>`).join(''):'<p class="subtle">No scenario-level regression passed the configured threshold.</p>'}${improvements.length?`<h4>Improvements</h4>${improvements.map(item=>`<div class="notice"><strong>${esc(item.scenario_id)} · ${esc(item.dimension)}</strong> ${esc(item.previous_score)} → ${esc(item.current_score)} (+${esc(item.delta)})</div>`).join('')}`:''}${persistent.length?`<h4>Persistent failures</h4>${persistent.map(item=>`<div class="notice error-notice"><strong>${esc(item.scenario_id)} · ${esc(item.dimension)}</strong> remains failed across runs</div>`).join('')}`:''}<p class="subtle">Last known-good baseline: ${comparisons.last_known_good?esc(comparisons.last_known_good):'none has passed human-reviewed calibration yet'}.</p>`}
