    const scenario=$('#personality-scenario-graph');if(scenario){const categories=Object.entries(currentPoint?.scenario_categories||{});scenario.innerHTML=categories.length?buildHorizontalBars(categories.map(([name,score])=>({name,value:score,label:`${score.toFixed(2)} / 4`})),4):'<div class="empty">No scored scenario categories in this run.</div>'}
